import { dirname, readBytes, resolvePath, type ByteSource, type CommandContext, type FileStat } from "../../contracts/index.js";
import { encodeEntry, type Entry } from "./format.js";
import { Budget, checkPath, display, fail, fileSource, hasIdentity, maybeStat, operation, sameIdentity, vfsPath } from "./internal.js";
import { Exclusions, type TarOptions } from "./options.js";

interface SourceEntry { readonly path: string; readonly stat: FileStat; readonly entry: Entry }

function safeName(name: string): string {
  const relative = name.replace(/^\/+/u, "");
  const components = relative.split("/");
  return components.slice(components.lastIndexOf("..") + 1).join("/") || ".";
}

export async function manifest(context: CommandContext, options: TarOptions, budget: Budget): Promise<{ entries: SourceEntry[]; output?: string; outputStat?: FileStat }> {
  const exclusions = new Exclusions(options.excludes, budget.limits.maxPatternSteps);
  const entries: SourceEntry[] = [];
  let output: string | undefined;
  let outputStat: FileStat | undefined;
  if (options.archive !== "-") {
    const path = vfsPath(context.cwd, options.archive);
    outputStat = await maybeStat(context, path);
    if (outputStat && outputStat.type !== "file") fail("output archive must be a regular file, not a symlink or directory");
    if (outputStat && !hasIdentity(outputStat)) fail("cannot safely replace an archive with unknown backing identity");
    const parent = await operation(context, () => context.fs.realpath(dirname(path), { signal: context.signal }));
    output = resolvePath(parent, path.slice(path.lastIndexOf("/") + 1));
  }
  const identities = new Map<object | symbol, Map<string, Map<string, SourceEntry>>>();
  const bindings = new Map<string, { scope: object | symbol; key: string }>();
  const visit = async (path: string, name: string, depth: number, explicit: boolean): Promise<void> => {
    checkPath(name, budget.limits);
    if (depth > budget.limits.maxDepth) fail("source traversal depth limit exceeded");
    await budget.member();
    if (exclusions.matches(name)) return;
    const stat = await operation(context, () => context.fs.lstat(path, { signal: context.signal }));
    const canonical = stat.type === "symlink" ? path : await operation(context, () => context.fs.realpath(path, { signal: context.signal }));
    if (output && (canonical === output || (outputStat && sameIdentity(stat, outputStat)))) {
      if (explicit) fail(`input is the output archive: ${display(name)}`);
      await budget.output(`tar: ${display(name)}: file is the archive; not included\n`, true);
      return;
    }
    if (stat.type !== "file" && stat.type !== "directory" && stat.type !== "symlink") fail(`unsupported source type: ${display(name)}`);
    const entry: Entry = {
      name: stat.type === "directory" && !name.endsWith("/") ? `${name}/` : name,
      type: stat.type === "directory" ? "5" : stat.type === "symlink" ? "2" : "0",
      linkname: "", size: stat.type === "file" ? stat.size : 0,
      mode: stat.mode & 0o7777, uid: stat.uid ?? 0, gid: stat.gid ?? 0,
      mtime: options.format === "ustar" ? Math.floor(stat.mtimeMs / 1000) : stat.mtimeMs / 1000,
    };
    if (options.format === "pax") entry.atime = stat.atimeMs / 1000;
    if (stat.type === "symlink") {
      if ((stat.nlink ?? 1) > 1) fail("hardlinked symbolic-link sources are unsupported");
      if (!context.fs.readlink) fail("filesystem does not support readlink");
      entry.linkname = await operation(context, () => context.fs.readlink!(path, { signal: context.signal }));
      checkPath(entry.linkname, budget.limits);
    }
    const archivePath = resolvePath("/", entry.name);
    const binding = bindings.get(archivePath);
    if (binding) {
      identities.get(binding.scope)?.get(binding.key)?.delete(archivePath);
      bindings.delete(archivePath);
    }
    if (stat.type === "file") {
      if (outputStat && !hasIdentity(stat)) fail("cannot replace an existing archive when a source has unknown backing identity");
      if ((stat.nlink ?? 1) > 1 && !hasIdentity(stat)) fail(`cannot preserve hardlinks without complete backing identity: ${display(name)}`);
      if (hasIdentity(stat)) {
        let scope = identities.get(stat.identityScope!);
        if (!scope) { scope = new Map(); identities.set(stat.identityScope!, scope); }
        const key = `${stat.dev}:${stat.ino}`;
        let paths = scope.get(key);
        if (!paths) { paths = new Map(); scope.set(key, paths); }
        const previous = paths.values().next().value;
        if (previous) {
          entry.type = "1"; entry.linkname = previous.entry.name; entry.size = 0;
        }
        paths.set(archivePath, { path, stat, entry });
        bindings.set(archivePath, { scope: stat.identityScope!, key });
      }
      if (!Number.isSafeInteger(entry.size) || entry.size < 0 || entry.size > budget.limits.maxEntryBytes) fail("entry byte limit exceeded");
      if (entry.size > budget.limits.maxTotalBytes - budget.totalBytes) fail("total payload byte limit exceeded");
      budget.totalBytes += entry.size;
    }
    const headers = encodeEntry(entry, budget.limits);
    if (options.format === "ustar" && headers.length > 1) fail(`metadata requires PAX format: ${display(name)}`);
    entries.push({ path, stat, entry });
    if (stat.type === "directory") {
      const children = await operation(context, () => context.fs.readdir(path, { signal: context.signal }));
      if (children.length > budget.limits.maxMembers - budget.members) fail("member/header limit exceeded");
      for (const child of children) {
        if (!child.name || child.name === "." || child.name === ".." || /[/\0]/u.test(child.name)) fail("invalid filesystem directory entry");
        await visit(resolvePath(canonical, child.name), `${entry.name}${child.name}`, depth + 1, false);
      }
    }
  };
  for (const operand of options.operands) {
    const base = await operation(context, () => context.fs.stat(operand.cwd, { signal: context.signal }));
    if (base.type !== "directory") fail(`not a directory: ${display(operand.cwd)}`);
    if (operand.name.startsWith("/")) await budget.output("tar: removing leading '/' from member names\n", true);
    if (operand.name.split("/").includes("..")) await budget.output("tar: removing member-name prefix through '..'\n", true);
    await visit(vfsPath(operand.cwd, operand.name), safeName(operand.name), 0, true);
  }
  return { entries, ...(output === undefined ? {} : { output }), ...(outputStat === undefined ? {} : { outputStat }) };
}

async function unchanged(context: CommandContext, source: SourceEntry): Promise<void> {
  const current = await operation(context, () => context.fs.lstat(source.path, { signal: context.signal }));
  if (current.type !== source.stat.type || (source.stat.type !== "directory" && (current.size !== source.stat.size || current.mtimeMs !== source.stat.mtimeMs
    || current.ctimeMs !== source.stat.ctimeMs)) || (hasIdentity(source.stat) && !sameIdentity(source.stat, current))) fail(`source changed while archiving: ${display(source.entry.name)}`);
  if (source.stat.type === "symlink") {
    const target = await operation(context, () => context.fs.readlink!(source.path, { signal: context.signal }));
    if (target !== source.entry.linkname) fail("source symlink changed while archiving");
  }
}

export async function* createArchive(context: CommandContext, entries: readonly SourceEntry[], options: TarOptions, budget: Budget): ByteSource {
  let headers = 0;
  for (const source of entries) {
    await unchanged(context, source);
    const encoded = encodeEntry(source.entry, budget.limits);
    headers += encoded.length > 1 ? 2 : 1;
    if (headers > budget.limits.maxMembers) fail("member/header limit exceeded");
    for (const chunk of encoded) if (chunk.length) yield chunk;
    if (options.verbose) await budget.output(`${display(source.entry.name)}\n`, options.archive === "-");
    if (source.entry.type === "0") {
      let bytes = 0;
      for await (const chunk of readBytes(fileSource(context, source.path, budget.limits), context.signal)) {
        if (chunk.length > source.entry.size - bytes) fail(`source grew while archiving: ${display(source.entry.name)}`);
        bytes += chunk.length;
        yield chunk;
      }
      if (bytes !== source.entry.size) fail(`source shrank while archiving: ${display(source.entry.name)}`);
      await unchanged(context, source);
      const padding = (512 - bytes % 512) % 512;
      if (padding) yield new Uint8Array(padding);
    }
  }
  yield new Uint8Array(1024);
}

import { dirname, isPathWithin, resolvePath, type ByteSource, type CommandContext, type FileStat } from "../../contracts/index.js";
import { applyPax, parseHeader, parsePax, type Entry } from "./format.js";
import { Budget, checkPath, display, fail, hasIdentity, maybeStat, operation, publish, sameIdentity, text, vfsPath } from "./internal.js";
import { Exclusions, type TarOptions } from "./options.js";
import { Reader } from "./stream.js";

function relativeName(name: string, strip: number): string | undefined {
  if (name.includes("\0")) fail("NUL in member name");
  const components = name.replace(/^\/+/u, "").split("/").filter(component => component !== "");
  if (components.includes("..")) fail(`unsafe parent component in member: ${display(name)}`);
  const stripped = components.slice(strip).filter(component => component !== ".");
  if (components.length <= strip) return undefined;
  return stripped.join("/");
}

async function checkRoot(context: CommandContext, root: string): Promise<void> {
  let path = "/";
  for (const component of root.split("/").filter(Boolean)) {
    path = resolvePath(path, component);
    const stat = await operation(context, () => context.fs.lstat(path, { signal: context.signal }));
    if (stat.type !== "directory") fail(`extraction root has a non-directory or symlink ancestor: ${display(path)}`);
  }
  const stat = await operation(context, () => context.fs.lstat(root, { signal: context.signal }));
  if (stat.type !== "directory") fail(`not an extraction directory: ${display(root)}`);
}

async function parents(context: CommandContext, root: string, path: string, create: boolean, allowMissing = false): Promise<void> {
  if (!isPathWithin(root, path)) fail("extraction path escapes root");
  await checkRoot(context, root);
  const relative = path.slice(root === "/" ? 1 : root.length + 1);
  let parent = root;
  for (const component of relative.split("/").slice(0, -1)) {
    if (!component) continue;
    parent = resolvePath(parent, component);
    const stat = await maybeStat(context, parent);
    if (!stat && create) await operation(context, () => context.fs.mkdir(parent, { signal: context.signal, mode: 0o700 }));
    else if ((!stat && !allowMissing) || (stat && stat.type !== "directory")) fail(`unsafe non-directory or symlink ancestor: ${display(parent)}`);
  }
}

async function removeExisting(context: CommandContext, path: string, stat: FileStat | undefined): Promise<void> {
  if (!stat) return;
  if (stat.type === "directory") {
    if (!context.fs.rmdir) fail("filesystem does not support safe empty-directory replacement");
    await operation(context, () => context.fs.rmdir!(path, { signal: context.signal }));
  } else await operation(context, () => context.fs.rm(path, { signal: context.signal }));
}

async function checkSymlinkTarget(context: CommandContext, root: string, path: string, target: string, budget: Budget): Promise<void> {
  if (target.startsWith("/")) fail(`symlink target escapes extraction root: ${display(path)}`);
  let current = dirname(path);
  let pending = target.split("/");
  let links = 0;
  let steps = 0;
  const safeComponents = (value: string): string[] => {
    const components = value.split("/");
    let descended = false;
    for (const component of components) {
      if (component === ".." && descended) fail("symlink targets with non-leading '..' components are unsafe under later link replacement");
      if (component !== ".." && component !== "." && component !== "") descended = true;
    }
    return components;
  };
  pending = safeComponents(target);
  while (pending.length) {
    if (++steps > budget.limits.maxDepth * 41) fail("symlink target resolution limit exceeded");
    const component = pending.shift()!;
    if (!component || component === ".") continue;
    if (component === "..") {
      if (current === root) fail(`symlink target escapes extraction root: ${display(path)}`);
      current = dirname(current);
      continue;
    }
    const candidate = resolvePath(current, component);
    if (!isPathWithin(root, candidate)) fail("symlink target escapes extraction root");
    const stat = await maybeStat(context, candidate);
    if (stat?.type === "symlink") {
      if (++links > 40 || !context.fs.readlink) fail("symlink target chain cannot be safely resolved");
      const link = await operation(context, () => context.fs.readlink!(candidate, { signal: context.signal }));
      checkPath(link, budget.limits);
      if (link.startsWith("/")) {
        if (root !== "/" && link !== root && !link.startsWith(`${root}/`)) fail("symlink target chain escapes extraction root");
        current = root;
        pending = [...safeComponents(link.slice(root === "/" ? 1 : root.length)), ...pending];
      } else pending = [...safeComponents(link), ...pending];
    } else current = candidate;
  }
}

async function metadata(context: CommandContext, path: string, entry: Entry): Promise<void> {
  if (context.fs.chmod && context.fs.capabilities.permissions !== false) {
    await operation(context, () => context.fs.chmod!(path, entry.mode & 0o777, { signal: context.signal }));
  }
  if (context.fs.utimes && context.fs.capabilities.timestamps !== false) {
    await operation(context, () => context.fs.utimes!(path, (entry.atime ?? entry.mtime) * 1000, entry.mtime * 1000, { signal: context.signal }));
  }
}

function verbose(entry: Entry): string {
  const type = entry.type === "5" ? "d" : entry.type === "2" ? "l" : entry.type === "1" ? "h" : "-";
  let permissions = "";
  for (const bit of [0o400, 0o200, 0o100, 0o040, 0o020, 0o010, 0o004, 0o002, 0o001]) permissions += entry.mode & bit ? (bit & 0o444 ? "r" : bit & 0o222 ? "w" : "x") : "-";
  for (const [offset, special, execute, lower, upper] of [[2, 0o4000, 0o100, "s", "S"], [5, 0o2000, 0o010, "s", "S"], [8, 0o1000, 0o001, "t", "T"]] as const) {
    if (entry.mode & special) permissions = permissions.slice(0, offset) + (entry.mode & execute ? lower : upper) + permissions.slice(offset + 1);
  }
  const suffix = entry.type === "2" ? ` -> ${display(entry.linkname)}` : entry.type === "1" ? ` link to ${display(entry.linkname)}` : "";
  return `${type}${permissions} ${entry.uid}/${entry.gid} ${entry.size} ${entry.mtime} ${display(entry.name)}${suffix}\n`;
}

export async function readArchive(context: CommandContext, source: ByteSource, options: TarOptions, budget: Budget): Promise<void> {
  const reader = new Reader(source, context.signal);
  const exclusions = new Exclusions(options.excludes, budget.limits.maxPatternSteps);
  const global = new Map<string, string>();
  let local = new Map<string, string>();
  let pending = false;
  let longName: string | undefined;
  let longLink: string | undefined;
  let warnedAbsolute = false;
  const matched = new Set<number>();
  const published = new Map<string, FileStat>();
  const directories = new Map<string, { root: string; entry: Entry }>();
  let archivePath: string | undefined;
  let archiveStat: FileStat | undefined;
  if (options.mode === "x" && options.archive !== "-") {
    archivePath = await operation(context, () => context.fs.realpath(vfsPath(context.cwd, options.archive), { signal: context.signal }));
    archiveStat = await operation(context, () => context.fs.stat(archivePath!, { signal: context.signal }));
  }
  if (options.mode === "x") await checkRoot(context, resolvePath(options.cwd));
  try {
    while (true) {
      const block = await reader.exact(512);
      if (block.every(byte => byte === 0)) {
        if (!(await reader.exact(512)).every(byte => byte === 0)) fail("missing second end-of-archive block");
        if (pending) fail("orphan extended header at end of archive");
        await reader.finish();
        break;
      }
      let entry = parseHeader(block);
      await budget.member();
      if (["x", "g", "L", "K"].includes(entry.type)) {
        if (entry.size > budget.limits.maxPaxBytes) fail("extended header byte limit exceeded");
        const payload = await reader.exact(entry.size);
        await reader.padding(entry.size);
        if (entry.type === "x" || entry.type === "g") {
          const values = parsePax(payload);
          if (entry.type === "g") {
            for (const [key, value] of values) value === "" ? global.delete(key) : global.set(key, value);
          } else { for (const [key, value] of values) local.set(key, value); pending = true; }
          for (const state of [global, local]) {
            if ([...state].reduce((size, [key, value]) => size + Buffer.byteLength(key) + Buffer.byteLength(value), 0) > budget.limits.maxPaxBytes) fail("PAX state byte limit exceeded");
          }
        } else {
          if (payload.length === 0 || payload.at(-1) !== 0) fail("invalid GNU long-name record");
          const value = text(payload.subarray(0, -1));
          checkPath(value, budget.limits);
          if (entry.type === "L") longName = value;
          else longLink = value;
          pending = true;
        }
        continue;
      }
      if (longName !== undefined) entry.name = longName;
      if (longLink !== undefined) entry.linkname = longLink;
      entry = applyPax(entry, global, local);
      local = new Map(); pending = false; longName = undefined; longLink = undefined;
      checkPath(entry.name, budget.limits);
      if (!Number.isFinite(entry.mtime) || Math.abs(entry.mtime * 1000) > 8.64e15) fail("archive timestamp is outside the supported range");
      if (entry.linkname) checkPath(entry.linkname, budget.limits);
      if (entry.type === "0" && entry.name.endsWith("/")) entry.type = "5";
      if (!["0", "1", "2", "5"].includes(entry.type)) fail(`unsupported archive entry type: ${display(entry.type)}`);
      if (entry.type !== "0" && entry.size !== 0) fail("non-file entry has a nonzero payload size");
      if (entry.size > budget.limits.maxEntryBytes) fail("entry byte limit exceeded");
      if (entry.size > budget.limits.maxTotalBytes - budget.totalBytes) fail("total payload byte limit exceeded");
      budget.totalBytes += entry.size;
      let relative: string | undefined;
      if (options.mode === "x") relative = relativeName(entry.name, options.strip);
      const name = entry.name.replace(/^\/+/u, "");
      let selected = options.operands.length === 0;
      let root = resolvePath(options.cwd);
      for (let index = 0; index < options.operands.length; index++) {
        const operand = options.operands[index]!;
        const wanted = operand.name.replace(/^\/+/u, "").replace(/\/+$/u, "");
        if (name.replace(/\/+$/u, "") === wanted || name.startsWith(`${wanted}/`)) {
          if (!selected) root = resolvePath(operand.cwd);
          selected = true;
          matched.add(index);
        }
      }
      if (!selected || exclusions.matches(name)) {
        await reader.discard(entry.size); await reader.padding(entry.size); continue;
      }
      if (options.mode === "t") {
        await budget.output(options.verbose ? verbose(entry) : `${display(entry.name)}\n`);
        await reader.discard(entry.size); await reader.padding(entry.size); continue;
      }
      if (entry.name.startsWith("/") && !warnedAbsolute) {
        await budget.output("tar: removing leading '/' from member names\n", true); warnedAbsolute = true;
      }
      if (relative === undefined) { await reader.discard(entry.size); await reader.padding(entry.size); continue; }
      const path = resolvePath(root, relative);
      if (path === root && entry.type !== "5") fail("non-directory entry would replace extraction root");
      let hardTarget: string | undefined;
      if (entry.type === "2") {
        await parents(context, root, path, false, true);
        checkPath(entry.linkname, budget.limits);
        await checkSymlinkTarget(context, root, path, entry.linkname, budget);
        if (!context.fs.symlink || context.fs.capabilities.symlinks === false) fail("filesystem does not support symbolic links");
      } else if (entry.type === "1") {
        checkPath(entry.linkname, budget.limits);
        const targetName = relativeName(entry.linkname, options.strip);
        if (targetName === undefined) fail("hardlink target removed by strip-components");
        hardTarget = resolvePath(root, targetName);
        if (hardTarget === path) fail("self-referential hardlink entry is unsupported");
        if (!published.has(hardTarget)) fail(`hardlink target was not previously extracted (forward or unselected target): ${display(entry.linkname)}`);
        await parents(context, root, hardTarget, false);
        const targetStat = await operation(context, () => context.fs.lstat(hardTarget!, { signal: context.signal }));
        if (targetStat.type !== "file" || (published.get(hardTarget)!.identityScope !== undefined && !sameIdentity(published.get(hardTarget)!, targetStat))) fail("hardlink target changed or is not a regular file");
        if (!context.fs.link || context.fs.capabilities.hardlinks === false) fail("filesystem does not support hardlinks");
      }
      await parents(context, root, path, true);
      const existing = await maybeStat(context, path);
      if (archivePath && (path === archivePath || (existing && archiveStat && sameIdentity(existing, archiveStat)))) fail("entry would overwrite the input archive");
      if (existing?.type === "file" && archiveStat && (!hasIdentity(existing) || !hasIdentity(archiveStat))) fail("cannot replace an existing file with unknown input-archive/destination backing identity");
      if (entry.type === "2") {
        await removeExisting(context, path, existing);
        published.delete(path); directories.delete(path);
        await operation(context, () => context.fs.symlink!(entry.linkname, path, { signal: context.signal }));
      } else if (entry.type === "1") {
        await removeExisting(context, path, existing);
        published.delete(path); directories.delete(path);
        await operation(context, () => context.fs.link!(hardTarget!, path, { signal: context.signal }));
        published.set(path, await operation(context, () => context.fs.lstat(path, { signal: context.signal })));
      } else if (entry.type === "5") {
        if (existing?.type !== "directory") {
          await removeExisting(context, path, existing);
          await operation(context, () => context.fs.mkdir(path, { signal: context.signal, mode: 0o700 }));
        }
        published.delete(path);
        directories.set(path, { root, entry });
      } else {
        await removeExisting(context, path, existing);
        published.delete(path); directories.delete(path);
        await publish(context, path, reader.body(entry.size));
        await metadata(context, path, entry);
        published.set(path, await operation(context, () => context.fs.lstat(path, { signal: context.signal })));
      }
      await reader.padding(entry.size);
      if (options.verbose) await budget.output(`${display(entry.name)}\n`);
    }
    for (let index = 0; index < options.operands.length; index++) if (!matched.has(index)) fail(`member not found: ${display(options.operands[index]!.name)}`);
    for (const [path, value] of [...directories].sort(([first], [second]) => second.length - first.length)) {
      await parents(context, value.root, path, false);
      const stat = await operation(context, () => context.fs.lstat(path, { signal: context.signal }));
      if (stat.type !== "directory") fail("directory changed before metadata restoration");
      await metadata(context, path, value.entry);
    }
  } finally {
    void reader.close().catch(() => {});
  }
}

import { checkPath, fail, text, type ArchiveLimits } from "./internal.js";

export interface Entry {
  name: string;
  type: string;
  linkname: string;
  size: number;
  mode: number;
  uid: number;
  gid: number;
  mtime: number;
  atime?: number;
}

export function numberField(header: Uint8Array, offset: number, width: number, signed = false): number {
  const bytes = header.subarray(offset, offset + width);
  let value: bigint;
  if (bytes[0]! & 0x80) {
    value = BigInt(bytes[0]! & 0x7f);
    for (const byte of bytes.subarray(1)) value = value * 256n + BigInt(byte);
    if (bytes[0]! & 0x40) value -= 1n << BigInt(width * 8 - 1);
  } else {
    const digits = Buffer.from(bytes).toString("latin1").replace(/^[ \0]+|[ \0]+$/gu, "");
    if (digits && !/^[0-7]+$/u.test(digits)) fail("invalid octal numeric field");
    value = digits ? BigInt(`0o${digits}`) : 0n;
  }
  const result = Number(value);
  if (!Number.isSafeInteger(result) || (!signed && result < 0)) fail("invalid or oversized numeric field");
  return result;
}

function stringField(header: Uint8Array, offset: number, width: number): string {
  const bytes = header.subarray(offset, offset + width);
  const end = bytes.indexOf(0);
  return text(end === -1 ? bytes : bytes.subarray(0, end));
}

export function parseHeader(header: Uint8Array): Entry {
  if (header.length !== 512) fail("invalid header size");
  const expected = numberField(header, 148, 8);
  let actual = 0;
  for (let offset = 0; offset < 512; offset++) actual += offset >= 148 && offset < 156 ? 32 : header[offset]!;
  if (actual !== expected) fail("header checksum mismatch");
  const magic = Buffer.from(header.subarray(257, 265)).toString("latin1");
  const posix = magic === "ustar\0" + "00";
  if (!posix && magic !== "ustar  \0") fail("unsupported archive format (expected USTAR, PAX, or GNU basic headers)");
  const prefix = posix ? stringField(header, 345, 155) : "";
  const name = stringField(header, 0, 100);
  const entry: Entry = {
    name: prefix ? `${prefix}/${name}` : name,
    type: header[156] === 0 ? "0" : String.fromCharCode(header[156]!),
    linkname: stringField(header, 157, 100),
    mode: numberField(header, 100, 8),
    uid: numberField(header, 108, 8),
    gid: numberField(header, 116, 8),
    size: numberField(header, 124, 12),
    mtime: numberField(header, 136, 12, true),
  };
  numberField(header, 329, 8);
  numberField(header, 337, 8);
  if (entry.mode > 0o7777) fail("invalid archive permission bits");
  return entry;
}

function octal(header: Uint8Array, offset: number, width: number, value: number): void {
  if (!Number.isSafeInteger(value) || value < 0 || value.toString(8).length >= width) fail("number does not fit USTAR field");
  header.set(Buffer.from(value.toString(8).padStart(width - 1, "0")), offset);
}

function splitName(name: string): [string, string] | undefined {
  if (!/^[\x01-\x7f]*$/u.test(name)) return undefined;
  if (Buffer.byteLength(name) <= 100) return [name, ""];
  for (let offset = name.length - 2; offset > 0; offset--) {
    if (name[offset] === "/" && Buffer.byteLength(name.slice(0, offset)) <= 155 && Buffer.byteLength(name.slice(offset + 1)) <= 100) {
      return [name.slice(offset + 1), name.slice(0, offset)];
    }
  }
  return undefined;
}

export function headerBytes(entry: Entry): Uint8Array {
  const split = splitName(entry.name);
  if (!split) fail("name does not fit USTAR header");
  if (Buffer.byteLength(entry.linkname) > 100) fail("link does not fit USTAR header");
  const header = new Uint8Array(512);
  header.set(Buffer.from(split[0]), 0);
  header.set(Buffer.from(split[1]), 345);
  octal(header, 100, 8, entry.mode);
  octal(header, 108, 8, entry.uid);
  octal(header, 116, 8, entry.gid);
  octal(header, 124, 12, entry.size);
  octal(header, 136, 12, entry.mtime);
  header.fill(32, 148, 156);
  header[156] = entry.type.charCodeAt(0);
  header.set(Buffer.from(entry.linkname), 157);
  header.set(Buffer.from("ustar\0" + "00"), 257);
  octal(header, 329, 8, 0);
  octal(header, 337, 8, 0);
  const checksum = header.reduce((sum, byte) => sum + byte, 0);
  header.set(Buffer.from(`${checksum.toString(8).padStart(6, "0")}\0 `), 148);
  return header;
}

export function paxRecord(key: string, value: string): Uint8Array {
  const payload = ` ${key}=${value}\n`;
  const bytes = Buffer.byteLength(payload);
  let size = bytes + 1;
  while (size !== bytes + String(size).length) size = bytes + String(size).length;
  return Buffer.from(`${size}${payload}`);
}

export function encodeEntry(entry: Entry, limits: ArchiveLimits): Uint8Array[] {
  checkPath(entry.name, limits);
  if (entry.linkname) checkPath(entry.linkname, limits);
  const base = { ...entry };
  if (!Number.isFinite(entry.mtime) || Math.abs(entry.mtime * 1000) > 8.64e15) fail("invalid source mtime");
  const records: Uint8Array[] = [];
  if (!splitName(base.name)) { records.push(paxRecord("path", base.name)); base.name = "PaxEntry"; }
  if (Buffer.byteLength(base.linkname) > 100 || /[^\x01-\x7f]/u.test(base.linkname)) {
    records.push(paxRecord("linkpath", base.linkname)); base.linkname = "";
  }
  for (const key of ["uid", "gid", "size", "mtime"] as const) {
    const value = base[key];
    const maximum = key === "uid" || key === "gid" ? 0o7777777 : 0o77777777777;
    if (!Number.isFinite(value) || (key !== "mtime" && (!Number.isSafeInteger(value) || value < 0))) fail(`invalid source ${key}`);
    if (!Number.isInteger(value) || value < 0 || value > maximum) {
      records.push(paxRecord(key, key === "mtime" ? decimalTime(value) : String(value))); base[key] = 0;
    }
  }
  if (entry.atime !== undefined) {
    if (!Number.isFinite(entry.atime) || Math.abs(entry.atime * 1000) > 8.64e15) fail("invalid source atime");
    records.push(paxRecord("atime", decimalTime(entry.atime)));
  }
  if (!records.length) return [headerBytes(base)];
  const payload = Buffer.concat(records);
  if (payload.length > limits.maxPaxBytes) fail("PAX header byte limit exceeded");
  const extension = headerBytes({ ...base, name: "PaxHeader", linkname: "", type: "x", size: payload.length, mode: 0o644 });
  return [extension, payload, new Uint8Array((512 - payload.length % 512) % 512), headerBytes(base)];
}

function decimalTime(value: number): string {
  return value.toFixed(9).replace(/(\.[0-9]*?)0+$/u, "$1").replace(/\.$/u, "");
}

const supportedKeywords = new Set(["path", "linkpath", "size", "uid", "gid", "mtime", "atime", "ctime", "uname", "gname", "comment", "charset", "hdrcharset"]);

export function parsePax(payload: Uint8Array): Map<string, string> {
  const result = new Map<string, string>();
  let offset = 0;
  while (offset < payload.length) {
    let space = offset;
    while (space < payload.length && payload[space] !== 32 && space - offset < 16) space++;
    const digits = Buffer.from(payload.subarray(offset, space)).toString("latin1");
    if (!/^[1-9][0-9]*$/u.test(digits) || payload[space] !== 32) fail("invalid PAX record length");
    const size = Number(digits);
    if (!Number.isSafeInteger(size) || size <= space - offset + 3 || size > payload.length - offset || payload[offset + size - 1] !== 10) fail("invalid PAX record framing");
    const record = text(payload.subarray(space + 1, offset + size - 1));
    const equals = record.indexOf("=");
    if (equals <= 0 || record.includes("\0")) fail("invalid PAX key/value");
    const key = record.slice(0, equals);
    const value = record.slice(equals + 1);
    if (!supportedKeywords.has(key)) fail(`unsupported PAX keyword: ${key}`);
    if (key === "hdrcharset" && value !== "" && value !== "ISO-IR 10646 2000 UTF-8") fail("unsupported PAX header charset");
    result.set(key, value);
    offset += size;
  }
  return result;
}

export function applyPax(entry: Entry, global: ReadonlyMap<string, string>, local: ReadonlyMap<string, string>): Entry {
  const result = { ...entry };
  const merged = new Map(global);
  for (const [key, value] of local) value === "" ? merged.delete(key) : merged.set(key, value);
  for (const [key, value] of merged) {
    if (key === "path") result.name = value;
    else if (key === "linkpath") result.linkname = value;
    else if (key === "uid" || key === "gid" || key === "size") {
      if (!/^[0-9]+$/u.test(value) || !Number.isSafeInteger(Number(value))) fail(`invalid PAX ${key}`);
      result[key] = Number(value);
    } else if (key === "mtime" || key === "atime" || key === "ctime") {
      if (!/^-?[0-9]+(?:\.[0-9]+)?$/u.test(value) || !Number.isFinite(Number(value)) || Math.abs(Number(value) * 1000) > 8.64e15) fail(`invalid PAX ${key}`);
      if (key !== "ctime") result[key] = Number(value);
    }
  }
  return result;
}

import { readBytes, writeBytes, type ByteSource, type CommandContext, type CommandDefinition, type VirtualShellPlugin } from "../../contracts/index.js";
import { createArchive, manifest } from "./create.js";
import { readArchive } from "./extract.js";
import { Budget, bounded, display, fail, fileSource, maybeStat, operation, publish, sameIdentity, settings, vfsPath, type ArchiveCommandsOptions } from "./internal.js";
import { parseOptions } from "./options.js";
import { compressed } from "./stream.js";

export { DEFAULT_ARCHIVE_LIMITS } from "./internal.js";
export type { ArchiveCommandsOptions, ArchiveLimits } from "./internal.js";

export function createTarCommand(options: ArchiveCommandsOptions = {}): CommandDefinition {
  const limits = settings(options);
  return { name: "tar", description: "Stream USTAR/PAX archives through the virtual filesystem", async execute(original) {
    original.signal.throwIfAborted();
    const controller = new AbortController();
    const signal = AbortSignal.any([original.signal, controller.signal]);
    const context: CommandContext = { ...original, signal };
    try {
      const parsed = await parseOptions(context, limits);
      const budget = new Budget(context, limits);
      if (parsed.mode === "c") {
        const prepared = await manifest(context, parsed, budget);
        let source: ByteSource = bounded(createArchive(context, prepared.entries, parsed, budget), limits.maxArchiveBytes, signal, limits.chunkSize);
        if (parsed.gzip) source = compressed(source, false, signal, limits);
        if (prepared.output) {
          const existing = await maybeStat(context, prepared.output);
          if (existing && existing.type !== "file") fail("output archive changed to a non-file");
          if (existing && (!prepared.outputStat || !sameIdentity(existing, prepared.outputStat))) fail("output archive backing entry changed during preparation");
          if (existing) await operation(context, () => context.fs.rm(prepared.output!, { signal }));
          await publish(context, prepared.output, source);
        } else {
          for await (const chunk of readBytes(source, signal)) await writeBytes(context.stdout, chunk, signal);
        }
      } else {
        let source = bounded(parsed.archive === "-" ? context.stdin : fileSource(context, vfsPath(context.cwd, parsed.archive), limits), limits.maxArchiveBytes, signal, limits.chunkSize);
        if (parsed.gzip) source = compressed(source, true, signal, limits);
        await readArchive(context, source, parsed, budget);
      }
      return { exitCode: 0 };
    } catch (error) {
      controller.abort(error);
      original.signal.throwIfAborted();
      const message = display((error instanceof Error ? error.message : String(error)).slice(0, 1024));
      await writeBytes(original.stderr, Buffer.from(`tar: ${message}\n`).subarray(0, limits.maxDiagnosticBytes), original.signal);
      return { exitCode: 2 };
    } finally { controller.abort(new Error("tar command finished")); }
  } };
}

export function createArchiveCommands(options: ArchiveCommandsOptions = {}): readonly CommandDefinition[] {
  return [createTarCommand(options)];
}

export function archiveCommands(options: ArchiveCommandsOptions = {}): VirtualShellPlugin {
  const commands = createArchiveCommands(options);
  return { name: "archive-commands", setup(host) {
    if (!options.replace && host.commands.has("tar")) throw new Error("Command already registered: tar");
    for (const command of commands) host.commands.register(command, { replace: options.replace ?? false });
  } };
}

import { collectBytes, readBytes, writeBytes, type ByteSource, type CommandContext, type FileStat } from "../../contracts/index.js";

export interface ArchiveLimits {
  readonly maxArchiveBytes: number;
  readonly maxEntryBytes: number;
  readonly maxTotalBytes: number;
  readonly maxMembers: number;
  readonly maxPathBytes: number;
  readonly maxDepth: number;
  readonly maxPaxBytes: number;
  readonly maxFilesFromBytes: number;
  readonly maxArgumentBytes: number;
  readonly maxTextBytes: number;
  readonly maxDiagnosticBytes: number;
  readonly maxPatternSteps: number;
  readonly maxBufferedFileBytes: number;
  readonly chunkSize: number;
}

export interface ArchiveCommandsOptions {
  readonly replace?: boolean;
  readonly limits?: Partial<ArchiveLimits>;
}

export const DEFAULT_ARCHIVE_LIMITS: Readonly<ArchiveLimits> = Object.freeze({
  maxArchiveBytes: 256 * 1024 * 1024,
  maxEntryBytes: 64 * 1024 * 1024,
  maxTotalBytes: 256 * 1024 * 1024,
  maxMembers: 10_000,
  maxPathBytes: 4096,
  maxDepth: 128,
  maxPaxBytes: 1024 * 1024,
  maxFilesFromBytes: 1024 * 1024,
  maxArgumentBytes: 64 * 1024,
  maxTextBytes: 1024 * 1024,
  maxDiagnosticBytes: 4096,
  maxPatternSteps: 10_000_000,
  maxBufferedFileBytes: 1024 * 1024,
  chunkSize: 64 * 1024,
});

export function settings(options: ArchiveCommandsOptions): ArchiveLimits {
  const limits = { ...DEFAULT_ARCHIVE_LIMITS, ...options.limits };
  for (const [key, value] of Object.entries(limits)) {
    if (!Object.hasOwn(DEFAULT_ARCHIVE_LIMITS, key) || !Number.isSafeInteger(value) || value < 1) throw new RangeError(`Invalid archive limit: ${key}`);
  }
  if (limits.chunkSize < 512 || limits.chunkSize > 1024 * 1024) throw new RangeError("Archive chunkSize must be between 512 and 1048576");
  return Object.freeze(limits);
}

export function fail(message: string): never { throw new Error(message); }

export function vfsPath(cwd: string, path: string): string {
  return path.startsWith("/") ? path : `${cwd === "/" ? "" : cwd}/${path}`;
}

export function wait<Value>(signal: AbortSignal, action: () => Value | PromiseLike<Value>): Promise<Value> {
  signal.throwIfAborted();
  return new Promise((resolve, reject) => {
    const abort = () => { signal.removeEventListener("abort", abort); reject(signal.reason); };
    signal.addEventListener("abort", abort, { once: true });
    try {
      Promise.resolve(action()).then(value => {
        signal.removeEventListener("abort", abort);
        resolve(value);
      }, error => { signal.removeEventListener("abort", abort); reject(error); });
    } catch (error) { signal.removeEventListener("abort", abort); reject(error); }
  });
}

export function operation<Value>(context: CommandContext, action: () => Value | PromiseLike<Value>): Promise<Value> {
  return wait(context.signal, action);
}

export async function maybeStat(context: CommandContext, path: string): Promise<FileStat | undefined> {
  try { return await operation(context, () => context.fs.lstat(path, { signal: context.signal })); }
  catch (error) {
    context.signal.throwIfAborted();
    if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") return undefined;
    throw error;
  }
}

export function hasIdentity(stat: FileStat): boolean {
  return ((typeof stat.identityScope === "object" && stat.identityScope !== null) || typeof stat.identityScope === "symbol")
    && Number.isSafeInteger(stat.dev) && stat.dev! >= 0 && Number.isSafeInteger(stat.ino) && stat.ino! >= 0;
}

export function sameIdentity(first: FileStat, second: FileStat): boolean {
  return hasIdentity(first) && hasIdentity(second) && first.identityScope === second.identityScope && first.dev === second.dev && first.ino === second.ino;
}

export function text(bytes: Uint8Array): string {
  try { return new TextDecoder("utf-8", { fatal: true }).decode(bytes); }
  catch { return fail("invalid UTF-8 archive name or metadata"); }
}

export function checkPath(path: string, limits: ArchiveLimits): void {
  if (!path || path.includes("\0") || Buffer.from(path).toString("utf8") !== path) fail("invalid empty, NUL, or non-Unicode path");
  if (Buffer.byteLength(path) > limits.maxPathBytes) fail("path byte limit exceeded");
  if (path.split("/").length > limits.maxDepth + 1) fail("path depth limit exceeded");
}

export function display(path: string): string {
  return path.replace(/[\\\x00-\x1f\x7f]/gu, character => {
    if (character === "\\") return "\\\\";
    if (character === "\n") return "\\n";
    if (character === "\r") return "\\r";
    if (character === "\t") return "\\t";
    return `\\${character.charCodeAt(0).toString(8).padStart(3, "0")}`;
  });
}

export class Budget {
  members = 0;
  totalBytes = 0;
  textBytes = 0;
  constructor(readonly context: CommandContext, readonly limits: ArchiveLimits) {}
  async member(size = 0): Promise<void> {
    this.context.signal.throwIfAborted();
    if (++this.members > this.limits.maxMembers) fail("member/header limit exceeded");
    if (!Number.isSafeInteger(size) || size < 0 || size > this.limits.maxEntryBytes) fail("entry byte limit exceeded");
    if (size > this.limits.maxTotalBytes - this.totalBytes) fail("total payload byte limit exceeded");
    this.totalBytes += size;
    if (this.members % 128 === 0) await wait(this.context.signal, () => new Promise<void>(resolve => setImmediate(resolve)));
  }
  async output(value: string, stderr = false): Promise<void> {
    const bytes = Buffer.from(value);
    if (bytes.length > this.limits.maxTextBytes - this.textBytes) fail("text output limit exceeded");
    this.textBytes += bytes.length;
    await writeBytes(stderr ? this.context.stderr : this.context.stdout, bytes, this.context.signal);
  }
}

export async function* bounded(source: ByteSource, maximum: number, signal: AbortSignal, chunkSize: number): ByteSource {
  let size = 0;
  let turns = 0;
  for await (const chunk of readBytes(source, signal)) {
    if (chunk.length > maximum - size) fail("archive byte limit exceeded");
    size += chunk.length;
    for (let offset = 0; offset < chunk.length; offset += chunkSize) {
      signal.throwIfAborted();
      yield chunk.subarray(offset, Math.min(chunk.length, offset + chunkSize));
    }
    if (++turns % 128 === 0) await wait(signal, () => new Promise<void>(resolve => setImmediate(resolve)));
  }
}

export async function* fileSource(context: CommandContext, path: string, limits: ArchiveLimits): ByteSource {
  context.signal.throwIfAborted();
  if (context.fs.readStream) {
    yield* readBytes(context.fs.readStream(path, { signal: context.signal, chunkSize: limits.chunkSize }), context.signal);
  } else {
    const stat = await operation(context, () => context.fs.stat(path, { signal: context.signal }));
    if (stat.size > limits.maxBufferedFileBytes) fail("filesystem lacks streaming reads: buffered file limit exceeded");
    const bytes = await operation(context, () => context.fs.readFile(path, { signal: context.signal, maxBytes: limits.maxBufferedFileBytes }));
    if (bytes.length > limits.maxBufferedFileBytes) fail("buffered file limit exceeded");
    yield bytes;
  }
}

export async function publish(context: CommandContext, path: string, source: ByteSource, mode = 0o600): Promise<void> {
  const options = { signal: context.signal, flag: "wx" as const, mode };
  if (context.fs.writeStream) {
    let finished = false;
    const observed = (async function* () { yield* readBytes(source, context.signal); finished = true; })();
    try {
      await operation(context, () => context.fs.writeStream!(path, observed, options));
      if (!finished) fail("filesystem writeStream returned before consuming its source");
    } finally { void observed.return(undefined).catch(() => {}); }
  } else {
    await operation(context, () => context.fs.writeFile(path, new Uint8Array(), options));
    for await (const chunk of readBytes(source, context.signal)) {
      await operation(context, () => context.fs.appendFile(path, chunk, { signal: context.signal }));
    }
  }
}

export async function smallFile(context: CommandContext, path: string, limits: ArchiveLimits): Promise<Uint8Array> {
  return collectBytes(fileSource(context, path, limits), { signal: context.signal, maxBytes: limits.maxFilesFromBytes });
}

import { collectBytes, type CommandContext } from "../../contracts/index.js";
import { checkPath, fail, operation, smallFile, text, vfsPath, type ArchiveLimits } from "./internal.js";

export interface Operand { readonly name: string; readonly cwd: string }
export interface TarOptions {
  mode: "c" | "t" | "x";
  archive: string;
  gzip: boolean;
  verbose: boolean;
  strip: number;
  format: "pax" | "ustar";
  cwd: string;
  operands: Operand[];
  excludes: string[];
}

export async function parseOptions(context: CommandContext, limits: ArchiveLimits): Promise<TarOptions> {
  if (context.args.reduce((total, argument) => total + Buffer.byteLength(argument), 0) > limits.maxArgumentBytes) fail("argument byte limit exceeded");
  let mode: TarOptions["mode"] | undefined;
  let archive = "-";
  let gzip = false;
  let verbose = false;
  let strip = 0;
  let format: TarOptions["format"] = "pax";
  let cwd = context.cwd;
  let nullFiles = false;
  let verbatim = false;
  let filesFrom = false;
  let stdinUsed = false;
  let filesFromBytes = 0;
  let lateExclude = false;
  const operands: Operand[] = [];
  const excludes: string[] = [];
  const operand = (name: string) => {
    checkPath(name, limits);
    if (operands.length >= limits.maxMembers) fail("operand limit exceeded");
    operands.push({ name, cwd });
  };
  const directory = async (name: string) => {
    checkPath(name, limits);
    const path = await operation(context, () => context.fs.realpath(vfsPath(cwd, name), { signal: context.signal }));
    const stat = await operation(context, () => context.fs.stat(path, { signal: context.signal }));
    if (stat.type !== "directory") fail(`not a directory: ${name}`);
    cwd = path;
  };
  const names = async (path: string) => {
    filesFrom = true;
    if (path === "-" && stdinUsed) fail("standard input file list can only be read once");
    const bytes = path === "-"
      ? await collectBytes(context.stdin, { maxBytes: limits.maxFilesFromBytes, signal: context.signal })
      : await smallFile(context, vfsPath(context.cwd, path), limits);
    if (path === "-") stdinUsed = true;
    filesFromBytes += bytes.length;
    if (filesFromBytes > limits.maxFilesFromBytes) fail("files-from byte limit exceeded");
    const contents = text(bytes);
    if (!nullFiles && contents.includes("\0")) fail("NUL in newline file list; use --null");
    const lines = contents.split(nullFiles ? "\0" : "\n");
    for (let index = 0; index < lines.length; index++) {
      const line = lines[index]!;
      if (!line) continue;
      if (!nullFiles && !verbatim && line.startsWith("-")) {
        if (line === "-C") {
          const next = lines[++index];
          if (!next) fail("missing -C argument in file list");
          await directory(next);
        } else if (line.startsWith("-C") && !/\s/u.test(line[2] ?? "")) await directory(line.slice(2));
        else if (line.startsWith("--directory=")) await directory(line.slice(12));
        else fail(`unsupported option in file list: ${line}; use --verbatim-files-from for literal names`);
      } else {
        if (!nullFiles && !verbatim && line.includes("\\")) fail("backslash quoting in file lists is unsupported; use --verbatim-files-from or --null");
        operand(line);
      }
    }
  };
  const apply = async (flag: string, value?: string) => {
    if (flag === "c" || flag === "t" || flag === "x") {
      if (mode) fail("exactly one of -c, -t, -x is required");
      mode = flag;
    } else if (flag === "z") gzip = true;
    else if (flag === "v") verbose = true;
    else if (flag === "f") { if (!value) fail("empty archive name"); archive = value; }
    else if (flag === "C") await directory(value!);
    else if (flag === "T") await names(value!);
    else if (flag === "exclude") { checkPath(value!, limits); if (operands.length) lateExclude = true; excludes.push(value!); }
    else if (flag === "strip-components") {
      if (!/^[0-9]+$/u.test(value!) || !Number.isSafeInteger(Number(value))) fail("invalid strip-components count");
      strip = Number(value);
    } else if (flag === "format") {
      if (value !== "ustar" && value !== "pax" && value !== "posix") fail(`unsupported archive format: ${value}`);
      format = value === "ustar" ? "ustar" : "pax";
    } else if (flag === "null") { nullFiles = true; verbatim = true; }
    else if (flag === "no-null") nullFiles = false;
    else if (flag === "verbatim-files-from") verbatim = true;
    else if (flag === "no-verbatim-files-from") verbatim = false;
    else fail(`unsupported option: ${flag}`);
  };
  const long: Record<string, string> = { create: "c", list: "t", extract: "x", get: "x", file: "f", gzip: "z", verbose: "v", directory: "C", "files-from": "T" };
  const values = new Set(["f", "C", "T", "exclude", "strip-components", "format"]);
  let end = false;
  for (let index = 0; index < context.args.length; index++) {
    const argument = context.args[index]!;
    if (!end && argument === "--") { end = true; continue; }
    if (!end && argument.startsWith("--")) {
      const equals = argument.indexOf("=");
      const name = argument.slice(2, equals < 0 ? undefined : equals);
      const flag = long[name] ?? name;
      let value = equals < 0 ? undefined : argument.slice(equals + 1);
      if (values.has(flag) && value === undefined) value = context.args[++index];
      if (values.has(flag) && value === undefined) fail(`missing argument for --${name}`);
      if (!values.has(flag) && value !== undefined) fail(`option --${name} does not take an argument`);
      await apply(flag, value);
    } else if (!end && ((argument.startsWith("-") && argument !== "-") || (index === 0 && /^[ctxzvfCT]+$/u.test(argument)))) {
      const old = !argument.startsWith("-");
      const cluster = old ? argument : argument.slice(1);
      for (let offset = 0; offset < cluster.length; offset++) {
        const flag = cluster[offset]!;
        let value: string | undefined;
        if (values.has(flag)) {
          value = !old && offset + 1 < cluster.length ? cluster.slice(offset + 1) : context.args[++index];
          if (value === undefined) fail(`missing argument for -${flag}`);
          if (!old) offset = cluster.length;
        }
        await apply(flag, value);
      }
    } else operand(argument);
  }
  if (!mode) fail("exactly one of -c, -t, -x is required");
  if (mode !== "c" && archive === "-" && stdinUsed) fail("archive and file list cannot both use standard input");
  if (mode === "c" && strip !== 0) fail("--strip-components is only supported when reading archives");
  if (mode === "c" && lateExclude) fail("--exclude after source operands is unsupported; place exclusions before operands");
  if (mode === "c" && !operands.length && !filesFrom) fail("refusing to create an empty archive without -T");
  if (archive !== "-") checkPath(archive, limits);
  return { mode, archive, gzip, verbose, strip, format, cwd, operands, excludes };
}

type Token = { kind: "star" } | { kind: "any" } | { kind: "literal"; value: string }
  | { kind: "class"; ranges: readonly [number, number][]; negative: boolean };

function tokenize(pattern: string): Token[] {
  const characters = Array.from(pattern);
  const tokens: Token[] = [];
  for (let index = 0; index < characters.length; index++) {
    const character = characters[index]!;
    if (character === "*") { if (tokens.at(-1)?.kind !== "star") tokens.push({ kind: "star" }); }
    else if (character === "?") tokens.push({ kind: "any" });
    else if (character === "\\") {
      if (++index === characters.length) fail("trailing escape in exclude pattern");
      tokens.push({ kind: "literal", value: characters[index]! });
    } else if (character === "[") {
      const ranges: [number, number][] = [];
      index++;
      const negative = characters[index] === "!" || characters[index] === "^";
      if (negative) index++;
      while (index < characters.length && (characters[index] !== "]" || ranges.length === 0)) {
        const first = characters[index]!;
        if (first === "[" || first === "\\") fail("POSIX classes and escapes inside exclude brackets are unsupported");
        let last = first;
        if (characters[index + 1] === "-" && characters[index + 2] && characters[index + 2] !== "]") {
          last = characters[index + 2]!; index += 2;
        }
        if (first.codePointAt(0)! > last.codePointAt(0)!) fail("invalid exclude bracket range");
        ranges.push([first.codePointAt(0)!, last.codePointAt(0)!]);
        index++;
      }
      if (characters[index] !== "]") fail("unclosed exclude bracket");
      tokens.push({ kind: "class", ranges, negative });
    } else tokens.push({ kind: "literal", value: character });
  }
  return tokens;
}

export class Exclusions {
  private readonly patterns: Token[][];
  private work = 0;
  constructor(patterns: readonly string[], readonly maxWork = 10_000_000) { this.patterns = patterns.map(tokenize); }
  matches(name: string): boolean {
    const characters = Array.from(name);
    for (const tokens of this.patterns) {
      let states = new Uint8Array(characters.length + 1);
      states[0] = 1;
      for (let index = 0; index < characters.length; index++) if (characters[index] === "/") states[index + 1] = 1;
      for (const token of tokens) {
        this.work += characters.length + 1;
        if (this.work > this.maxWork) fail("exclude pattern work limit exceeded");
        const next = new Uint8Array(states.length);
        for (let index = 0; index < states.length; index++) {
          if (token.kind === "star") next[index] = states[index]! || (index > 0 ? next[index - 1]! : 0);
          else if (states[index] && index < characters.length) {
            const character = characters[index]!;
            const matches = token.kind === "any" || (token.kind === "literal" ? token.value === character
              : token.ranges.some(([first, last]) => character.codePointAt(0)! >= first && character.codePointAt(0)! <= last) !== token.negative);
            if (matches) next[index + 1] = 1;
          }
        }
        states = next;
      }
      for (let index = 0; index < states.length; index++) if (states[index] && (index === characters.length || characters[index] === "/")) return true;
    }
    return false;
  }
}

import { createGunzip, createGzip } from "node:zlib";
import { readBytes, type ByteSource } from "../../contracts/index.js";
import { bounded, fail, wait, type ArchiveLimits } from "./internal.js";

export async function* compressed(source: ByteSource, decode: boolean, signal: AbortSignal, limits: ArchiveLimits): ByteSource {
  signal.throwIfAborted();
  const controller = new AbortController();
  const combined = AbortSignal.any([signal, controller.signal]);
  const streamOptions = { chunkSize: limits.chunkSize, highWaterMark: limits.chunkSize };
  const transform = decode ? createGunzip(streamOptions) : createGzip(streamOptions);
  transform.on("error", () => {});
  const destroy = () => { transform.destroy(new Error("archive compression cancelled")); };
  combined.addEventListener("abort", destroy, { once: true });
  const pump = (async () => {
    try {
      for await (const chunk of bounded(source, limits.maxArchiveBytes, combined, limits.chunkSize)) {
        await wait(combined, () => new Promise<void>((resolve, reject) => {
          transform.write(chunk, error => error ? reject(error) : resolve());
        }));
      }
      combined.throwIfAborted();
      transform.end();
    } catch (error) {
      transform.destroy(error instanceof Error ? error : new Error(String(error)));
      throw error;
    }
  })();
  void pump.catch(() => {});
  try {
    yield* bounded(transform, limits.maxArchiveBytes, combined, limits.chunkSize);
    await pump;
  } finally {
    controller.abort(new Error("archive compression finished"));
    combined.removeEventListener("abort", destroy);
    transform.destroy();
    await pump.catch(() => {});
  }
}

export class Reader {
  readonly iterator: AsyncIterator<Uint8Array>;
  private chunk: Uint8Array = new Uint8Array();
  private offset = 0;
  constructor(source: ByteSource, readonly signal: AbortSignal) {
    this.iterator = readBytes(source, signal)[Symbol.asyncIterator]();
  }
  async take(maximum: number): Promise<Uint8Array | undefined> {
    this.signal.throwIfAborted();
    while (this.offset === this.chunk.length) {
      const result = await this.iterator.next();
      if (result.done) return undefined;
      this.chunk = result.value;
      this.offset = 0;
    }
    const end = Math.min(this.chunk.length, this.offset + maximum);
    const bytes = this.chunk.subarray(this.offset, end);
    this.offset = end;
    return bytes;
  }
  async exact(size: number): Promise<Uint8Array> {
    const result = new Uint8Array(size);
    let offset = 0;
    while (offset < size) {
      const bytes = await this.take(size - offset);
      if (!bytes) fail("truncated archive");
      result.set(bytes, offset);
      offset += bytes.length;
    }
    return result;
  }
  async *body(size: number): ByteSource {
    let remaining = size;
    while (remaining > 0) {
      const bytes = await this.take(remaining);
      if (!bytes) fail("truncated archive body");
      remaining -= bytes.length;
      yield bytes;
    }
  }
  async discard(size: number): Promise<void> {
    for await (const _chunk of this.body(size)) this.signal.throwIfAborted();
  }
  async padding(size: number): Promise<void> { await this.discard((512 - size % 512) % 512); }
  async finish(): Promise<void> {
    let trailing = 0;
    while (true) {
      const bytes = await this.take(64 * 1024);
      if (!bytes) break;
      if (bytes.some(byte => byte !== 0)) fail("nonzero trailing archive data or concatenated archive is unsupported");
      trailing += bytes.length;
    }
    if (trailing % 512 !== 0) fail("truncated archive trailing record");
  }
  async close(): Promise<void> {
    if (this.iterator.return) await this.iterator.return();
  }
}

import { dirname, FsError, isPathWithin, joinPath, type CommandContext, type FileStat } from "../contracts/index.js";
import { compareCopyIdentity } from "./copy-identity.js";
import { codeOf } from "./internal.js";

interface MoveEntry {
  readonly source: string;
  readonly target: string;
  readonly stat: FileStat;
  readonly targetStat: FileStat | undefined;
  readonly link: string | undefined;
}

async function optionalStat(context: CommandContext, path: string): Promise<FileStat | undefined> {
  try { return await context.fs.lstat(path, { signal: context.signal }); }
  catch (error) { context.signal.throwIfAborted(); if (codeOf(error) === "ENOENT") return undefined; throw error; }
}

function unchanged(before: FileStat, after: FileStat, content: boolean): boolean {
  const identity = compareCopyIdentity(before, after);
  const stableIdentity = compareCopyIdentity(before, before) === "same" ? identity === "same" : identity !== "distinct";
  return stableIdentity && before.type === after.type
    && (!content || (before.size === after.size && before.mtimeMs === after.mtimeMs && before.mode === after.mode));
}

async function recheck(context: CommandContext, entry: MoveEntry, content = true): Promise<void> {
  context.signal.throwIfAborted();
  const current = await context.fs.lstat(entry.source, { signal: context.signal });
  if (!unchanged(entry.stat, current, content)) throw new FsError("EBUSY", { path: entry.source, message: "move source changed before removal" });
}

export async function moveAcrossDevices(context: CommandContext, source: string, target: string, noClobber: boolean): Promise<boolean> {
  const plan: MoveEntry[] = [];
  let steps = 0;
  const step = async (): Promise<void> => {
    context.signal.throwIfAborted();
    if (++steps > 100_000) throw new FsError("EFBIG", { message: "cross-device move entry limit exceeded" });
    if (steps % 128 === 0) await new Promise<void>(resolve => setImmediate(resolve));
    context.signal.throwIfAborted();
  };
  const sourceStat = await context.fs.lstat(source, { signal: context.signal });
  const targetStat = await optionalStat(context, target);
  if (noClobber && targetStat) return false;
  if (source === target || compareCopyIdentity(sourceStat, targetStat) === "same") return false;
  if (source === "/") throw new FsError("EBUSY", { path: source });
  if (sourceStat.type === "directory") {
    if (!context.fs.rmdir) throw new FsError("ENOTSUP", { syscall: "rmdir", path: source });
    if (isPathWithin(source, target)) throw new FsError("EINVAL", { path: target, message: "cannot move a directory into itself" });
    let parent = dirname(target);
    while (true) {
      await step();
      const parentStat = await optionalStat(context, parent);
      if (compareCopyIdentity(sourceStat, parentStat) === "same") throw new FsError("EINVAL", { path: target, message: "cannot move a directory into itself" });
      if (parent === "/") break;
      parent = dirname(parent);
    }
  }
  const visit = async (origin: string, destination: string, stat: FileStat, existing: FileStat | undefined, depth: number): Promise<void> => {
    await step();
    if (depth > 128) throw new FsError("EFBIG", { message: "cross-device move depth limit exceeded" });
    if (existing) {
      const identity = compareCopyIdentity(stat, existing);
      if (identity === "same") throw new FsError("EINVAL", { path: origin, dest: destination, message: "move source and destination are aliases" });
      if (identity === "unknown") throw new FsError("ENOTSUP", { path: origin, dest: destination, message: "existing move destination lacks authoritative distinctness" });
      if ((stat.type === "directory") !== (existing.type === "directory")) throw new FsError(existing.type === "directory" ? "EISDIR" : "ENOTDIR", { path: destination });
      if (stat.type === "directory" && (await context.fs.readdir(destination, { signal: context.signal })).length) throw new FsError("ENOTEMPTY", { path: destination });
    }
    let link: string | undefined;
    if (stat.type === "symlink") {
      if (!context.fs.readlink || !context.fs.symlink) throw new FsError("ENOTSUP", { syscall: "symlink", path: origin });
      link = await context.fs.readlink(origin, { signal: context.signal });
    }
    plan.push({ source: origin, target: destination, stat, targetStat: existing, link });
    if (stat.type === "directory") {
      const entries = await context.fs.readdir(origin, { signal: context.signal });
      if (entries.length > 100_000 - steps) throw new FsError("EFBIG", { message: "cross-device move entry limit exceeded" });
      for (const entry of entries.sort((left, right) => left.name < right.name ? -1 : left.name > right.name ? 1 : 0)) {
        const child = joinPath(origin, entry.name), childTarget = joinPath(destination, entry.name);
        await visit(child, childTarget, await context.fs.lstat(child, { signal: context.signal }), await optionalStat(context, childTarget), depth + 1);
      }
    }
  };
  await visit(source, target, sourceStat, targetStat, 0);
  for (const entry of plan) {
    await recheck(context, entry);
    try {
      if (entry.stat.type === "directory") {
        if (!entry.targetStat) await context.fs.mkdir(entry.target, { mode: 0o700, signal: context.signal });
      } else if (entry.stat.type === "symlink") {
        if (entry.targetStat) await context.fs.rm(entry.target, { recursive: false, signal: context.signal });
        await context.fs.symlink!(entry.link!, entry.target, { signal: context.signal });
      } else {
        if (entry.targetStat?.type === "symlink") await context.fs.rm(entry.target, { recursive: false, signal: context.signal });
        await context.fs.copyFile(entry.source, entry.target, { exclusive: !entry.targetStat || entry.targetStat.type === "symlink", signal: context.signal });
      }
    } catch (error) {
      context.signal.throwIfAborted();
      if (noClobber && entry === plan[0] && !entry.targetStat && codeOf(error) === "EEXIST") return false;
      throw error;
    }
  }
  for (const entry of [...plan].reverse()) {
    context.signal.throwIfAborted();
    if (entry.stat.type !== "symlink") {
      if (context.fs.capabilities.permissions === true && context.fs.chmod) await context.fs.chmod(entry.target, entry.stat.mode & 0o7777, { signal: context.signal });
      if (context.fs.capabilities.timestamps === true && context.fs.utimes) await context.fs.utimes(entry.target, entry.stat.atimeMs, entry.stat.mtimeMs, { signal: context.signal });
    }
  }
  for (const entry of plan) await recheck(context, entry);
  for (const entry of [...plan].reverse()) {
    await recheck(context, entry, entry.stat.type !== "directory");
    if (entry.stat.type === "directory") await context.fs.rmdir!(entry.source, { signal: context.signal });
    else await context.fs.rm(entry.source, { recursive: false, signal: context.signal });
  }
  return true;
}
